from dataclasses import dataclass

@dataclass
class TaskResult:
    status: str
    result: object = None
    error: str = None
    func_name: str = None

class TaskRunner:
    def __init__(self):
        self.tasks = []
        self.results = []

    def add_task(self, func, *args, **kwargs):
        self.tasks.append((func, args, kwargs))

    def run(self):
        self.results = []
        for func, args, kwargs in self.tasks:
            try:
                result = func(*args, **kwargs)
                self.results.append(TaskResult(status='ok', result=result))
            except Exception as e:
                self.results.append(TaskResult(status='error', error=str(e), func_name=func.__name__))
        return self.results

    @property
    def summary(self):
        return {
            'errors': [r for r in self.results if r.status == 'error'],
            'successes': [r for r in self.results if r.status == 'ok']
        }
